-- Conferência da 060, SÓ LEITURA. Rode no SQL Editor depois de aplicar supabase/060_central_fiscal_rotinas.sql. Esperado: tudo "ok".
-- 1) colunas novas e restrições; 2) tabela de consultas com RLS, sem anon, só SELECT para quem entrou, políticas casa + mfa restritiva; 3) as 5 funções da rotina: definer, search_path vazio, só o service_role executa;
-- 4) nota_fiscal_confirmar com a trava de 60%; 5) a fonte 'consulta_oficial' aceita no histórico; 6) job fiscal-entradas agendado (se o pg_cron existir); 7) auditoria conhece a tabela nova.
select 'colunas_entradas' as item, case when (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'notas_fiscais_entradas' and column_name in ('proxima_em', 'origem')) = 2 then 'ok' else 'ERRO' end as resultado
union all select 'confirmado_pode_ser_nulo_so_na_reconciliacao', case when exists (select 1 from pg_constraint where conrelid = 'public.notas_fiscais_entradas'::regclass and conname = 'notas_fiscais_entradas_conf_ok') then 'ok' else 'ERRO' end
union all select 'fonte_consulta_oficial', case when exists (select 1 from pg_constraint where conrelid = 'public.notas_fiscais_situacoes'::regclass and pg_get_constraintdef(oid) like '%consulta_oficial%') then 'ok' else 'ERRO' end
union all select 'confirmar_tem_trava_60', case when pg_get_functiondef('public.nota_fiscal_confirmar(text,jsonb,jsonb,jsonb,jsonb,boolean,jsonb)'::regprocedure) like '%abaixo do mínimo de 60%' then 'ok' else 'ERRO' end
union all select 'job_fiscal_entradas', case when to_regnamespace('cron') is null then 'sem pg_cron (ok se não usa cron)' when exists (select 1 from cron.job where jobname = 'fiscal-entradas' and active) then 'ok' else 'ERRO' end
union all select 'auditoria_conhece_consultas', case when pg_get_functiondef('public.seguranca_estado()'::regprocedure) like '%notas_fiscais_consultas%' or (to_regclass('public.seguranca_catalogo') is not null and exists (select 1 from public.seguranca_catalogo where tabela = 'notas_fiscais_consultas')) then 'ok' else 'ERRO' end;
select 'tabela_consultas_rls_sem_anon_so_select' as item,
       case when c.relrowsecurity and not has_table_privilege('anon', c.oid, 'select') and (select string_agg(a.privilege_type, ',' order by a.privilege_type) from aclexplode(c.relacl) a where a.grantee = 'authenticated'::regrole) = 'SELECT' then 'ok' else 'ERRO' end as resultado
  from pg_class c where c.oid = 'public.notas_fiscais_consultas'::regclass;
select p.policyname as politica, case when (p.policyname = 'casa' and p.permissive = 'PERMISSIVE' and p.cmd = 'SELECT') or (p.policyname = 'mfa' and p.permissive = 'RESTRICTIVE') then 'ok' else 'ERRO' end as resultado from pg_policies p where p.schemaname = 'public' and p.tablename = 'notas_fiscais_consultas';
select p.proname as funcao, case when p.prosecdef and p.proconfig @> array['search_path=""'] and not has_function_privilege('anon', p.oid, 'execute') and not has_function_privilege('authenticated', p.oid, 'execute') and has_function_privilege('service_role', p.oid, 'execute') then 'ok' else 'ERRO' end as so_service_role
  from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('nf_validacao_pendentes', 'nf_validacao_registrar', 'nf_entradas_retomar', 'nf_entradas_reconciliar', 'nf_rotina_fiscal_sql');
